CREATE OR REPLACE FUNCTION public.celo_post_entry_atomic(p_room_id uuid, p_user_id uuid, p_amount integer, p_reference text, p_description text DEFAULT 'C-Lo table entry'::text, p_ledger_type text DEFAULT 'celo_entry'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.celo_rooms%ROWTYPE;
  v_player public.celo_room_players%ROWTYPE;
  v_now timestamptz := now();
  v_status text;
  v_desc text := COALESCE(NULLIF(trim(p_description), ''), 'C-Lo table entry');
  v_type text := COALESCE(NULLIF(trim(p_ledger_type), ''), 'celo_entry');
  v_min_entry integer;
  v_max_bank integer;
BEGIN
  IF p_room_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'room_id and user_id required');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'amount must be positive');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  SELECT *
  INTO v_room
  FROM public.celo_rooms
  WHERE id = p_room_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Room not found');
  END IF;

  v_min_entry := GREATEST(
    500,
    COALESCE(v_room.minimum_entry_sc, v_room.min_bet_cents, 100)
  );
  v_max_bank := GREATEST(
    0,
    COALESCE(v_room.current_bank_sc, v_room.current_bank_cents, 0)::integer
  );

  IF p_amount < v_min_entry THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bet must be at least the room minimum.');
  END IF;
  IF v_max_bank <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Table bank is empty.');
  END IF;
  IF p_amount > v_max_bank THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bet cannot exceed the current bank.');
  END IF;

  v_status := trim(COALESCE(v_room.status, ''));
  IF v_status = 'rolling' OR v_status = 'completed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Cannot post entry for this room state');
  END IF;
  IF v_status <> ALL (ARRAY['waiting', 'active', 'entry_phase']) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Entries cannot be posted in this room state');
  END IF;

  IF v_room.banker_id IS NOT NULL AND v_room.banker_id = p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'The banker cannot post a player entry');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.celo_rounds r
    WHERE r.room_id = p_room_id
      AND r.status IN ('banker_rolling', 'player_rolling', 'betting')
    LIMIT 1
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'A round is already in progress');
  END IF;

  SELECT *
  INTO v_player
  FROM public.celo_room_players
  WHERE room_id = p_room_id
    AND user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'You are not seated at this table');
  END IF;

  IF lower(trim(COALESCE(v_player.role, ''))) <> 'player' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Only players in a player seat can post an entry');
  END IF;

  IF v_player.entry_posted IS TRUE
     OR COALESCE(v_player.stake_amount_sc, 0) > 0
     OR COALESCE(v_player.entry_sc, 0) > 0
     OR COALESCE(v_player.bet_cents, 0) > 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'You already posted an entry for this round');
  END IF;

  UPDATE public.users u
  SET gpay_coins = u.gpay_coins - p_amount
  WHERE u.id = p_user_id
    AND u.gpay_coins >= p_amount;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient GPay Coins for this entry');
  END IF;

  INSERT INTO public.coin_transactions (
    user_id,
    type,
    gold_coins,
    gpay_coins,
    description,
    reference
  )
  VALUES (
    p_user_id,
    v_type,
    0,
    -p_amount,
    v_desc,
    p_reference
  );

  UPDATE public.celo_room_players
  SET
    entry_sc = p_amount,
    bet_cents = p_amount,
    entry_posted = true,
    stake_amount_sc = p_amount,
    status = 'active',
    player_seat_status = 'active'
  WHERE room_id = p_room_id
    AND user_id = p_user_id;

  IF v_status IN ('waiting', 'entry_phase') THEN
    UPDATE public.celo_rooms
    SET
      status = CASE WHEN v_status = 'waiting' THEN 'active' ELSE 'entry_phase' END,
      last_activity = v_now
    WHERE id = p_room_id;
  ELSE
    UPDATE public.celo_rooms
    SET last_activity = v_now
    WHERE id = p_room_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_next_free_player_seat(p_room_id uuid, p_cap integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  cap integer := GREATEST(2, LEAST(99, COALESCE(NULLIF(p_cap, 0), 10)));
  s integer;
BEGIN
  FOR s IN 1..(cap - 1) LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.celo_room_players crp
      WHERE crp.room_id = p_room_id
        AND crp.seat_number IS NOT NULL
        AND crp.seat_number = s
    ) THEN
      RETURN s;
    END IF;
  END LOOP;
  RETURN 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_record_platform_fee(p_round_id uuid, p_fee_type text, p_amount_cents integer, p_description text, p_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_amount integer := GREATEST(0, COALESCE(p_amount_cents, 0));
  v_fee_type text := COALESCE(NULLIF(trim(p_fee_type), ''), 'celo_main_fee');
  v_desc text := COALESCE(NULLIF(trim(p_description), ''), 'C-Lo platform fee');
  v_key text := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    CASE
      WHEN p_round_id IS NULL THEN NULL
      ELSE 'celo_fee:' || p_round_id::text || ':' || v_fee_type
    END
  );
  v_inserted_id uuid;
BEGIN
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'non_positive_amount');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'idempotency_key_required');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.platform_earnings pe WHERE pe.idempotency_key = v_key
  ) THEN
    RETURN jsonb_build_object('inserted', false, 'idempotency_key', v_key);
  END IF;

  BEGIN
    INSERT INTO public.platform_earnings (
      source,
      source_id,
      amount_cents,
      description,
      user_id,
      round_id,
      fee_type,
      idempotency_key
    )
    VALUES (
      'celo_game',
      CASE WHEN p_round_id IS NULL THEN NULL ELSE p_round_id::text END,
      v_amount,
      v_desc,
      p_user_id,
      p_round_id,
      v_fee_type,
      v_key
    )
    RETURNING id INTO v_inserted_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object('inserted', false, 'idempotency_key', v_key);
  END;

  PERFORM public.platform_record_revenue(v_amount, 'celo_fee');

  RETURN jsonb_build_object('inserted', true, 'id', v_inserted_id, 'idempotency_key', v_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.celo_reconcile_terminal_room_bank(p_round_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  v_delta integer;
  v_new_bank integer;
BEGIN
  IF p_round_id IS NULL THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'missing_round_id');
  END IF;

  SELECT
    id,
    room_id,
    status,
    banker_dice_result,
    banker_winnings_sc,
    terminal_bank_delta_sc,
    terminal_room_bank_applied
  INTO r
  FROM public.celo_rounds
  WHERE id = p_round_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'round_not_found');
  END IF;

  IF r.status <> 'completed' THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'round_not_completed');
  END IF;

  IF r.terminal_room_bank_applied IS TRUE THEN
    RETURN jsonb_build_object(
      'reconciled', false,
      'reason', 'already_applied',
      'new_bank_sc', (
        SELECT COALESCE(current_bank_sc, 0)::integer FROM public.celo_rooms WHERE id = r.room_id
      )
    );
  END IF;

  v_delta := r.terminal_bank_delta_sc;
  IF v_delta IS NULL THEN
    RETURN jsonb_build_object(
      'reconciled', false,
      'reason', 'no_stored_delta_set_terminal_bank_delta_sc_manually'
    );
  END IF;

  IF v_delta = 0 THEN
    UPDATE public.celo_rounds SET terminal_room_bank_applied = true WHERE id = p_round_id;
    RETURN jsonb_build_object(
      'reconciled', true,
      'reason', 'zero_delta_marked',
      'new_bank_sc', (
        SELECT COALESCE(current_bank_sc, 0)::integer FROM public.celo_rooms WHERE id = r.room_id
      )
    );
  END IF;

  UPDATE public.celo_rooms AS c
  SET
    current_bank_sc = GREATEST(0, COALESCE(c.current_bank_sc, 0) + v_delta),
    current_bank_cents = GREATEST(0, COALESCE(c.current_bank_sc, 0) + v_delta)
  WHERE c.id = r.room_id
  RETURNING c.current_bank_sc INTO v_new_bank;

  UPDATE public.celo_rounds
  SET terminal_room_bank_applied = true,
      terminal_bank_delta_sc = COALESCE(terminal_bank_delta_sc, v_delta)
  WHERE id = p_round_id;

  RETURN jsonb_build_object(
    'reconciled', true,
    'reason', 'applied',
    'new_bank_sc', COALESCE(v_new_bank, 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_coins_with_ledger(p_user_id uuid, p_gold_coins integer, p_gpay_coins integer, p_type text, p_description text, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_g integer := COALESCE(p_gold_coins, 0);
  v_s integer := COALESCE(p_gpay_coins, 0);
  v_type text;
  v_desc text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'user_id required');
  END IF;
  IF v_g = 0 AND v_s = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Amount cannot be zero');
  END IF;
  IF p_reference IS NULL OR trim(p_reference) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'reference required');
  END IF;

  IF EXISTS (SELECT 1 FROM public.coin_transactions WHERE reference = p_reference) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Duplicate transaction');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'User not found');
  END IF;

  v_type := COALESCE(NULLIF(trim(p_type), ''), 'credit');
  v_desc := COALESCE(NULLIF(trim(p_description), ''), 'Credit');

  PERFORM public.credit_coins(p_user_id, v_g, v_s);

  INSERT INTO public.coin_transactions (user_id, type, gold_coins, gpay_coins, description, reference)
  VALUES (p_user_id, v_type, v_g, v_s, v_desc, p_reference);

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.debit_gpay_coins(p_user_id uuid, p_amount integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_current_balance integer;
BEGIN
  -- Get current balance
  SELECT gpay_coins
  INTO v_current_balance
  FROM users
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'User not found'
    );
  END IF;

  -- Check sufficient balance
  IF v_current_balance < p_amount THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Insufficient GPay Coins',
      'balance', v_current_balance,
      'required', p_amount
    );
  END IF;

  -- Deduct coins
  UPDATE users
  SET
    gpay_coins = gpay_coins - p_amount,
    updated_at = now()
  WHERE id = p_user_id;

  RETURN json_build_object(
    'success', true,
    'debited', p_amount,
    'new_balance', v_current_balance - p_amount
  );

EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$function$
